    console.error('V4.02 worldboss profile stats',e);
  }
};

const v116BaseRender=render;
render=function(){
  const result=v116BaseRender();

  return result;
};

/* Push current stats once after upgrade. */
setTimeout(async()=>{
  try{
    if(v073Ready){
      v112EnsureWorldBossState();
      await v073SyncProfile(true);
    }
  }catch(e){}
},1800);
</script>


